exercises.solution:
let essais=0;
let valide=false;
let nombre=0;
while(!valide&&essais<3){const texte=input("Entier ?").trim();nombre=Number(texte);valide=texte!==""&&Number.isInteger(nombre)&&nombre>=1&&nombre<=5;essais=essais+1;}
if(valide){console.log(nombre);}else{console.log("Invalide");}

